def reorder_by_priority_with_fallback_alpha(items, priority):
    rank = {p: i for i, p in enumerate(priority)}
    front = sorted((x for x in items if x in rank), key=lambda x: rank[x])
    back = sorted(x for x in items if x not in rank)
    return front + back

