def dense_rank(nums):
    unique_sorted = []
    for x in nums:
        if x not in unique_sorted:
            unique_sorted.append(x)
    unique_sorted.sort()
    rank_lookup = {}
    for i, v in enumerate(unique_sorted):
        rank_lookup[v] = i + 1
    return [rank_lookup[x] for x in nums]

